// PreToolUse (Edit|Write): plugins/*/.claude-plugin/types/ is written by Claude Code when it loads a plugin.
import { readFileSync } from "node:fs";
import { resolve } from "node:path";

let input;
try {
  input = JSON.parse(readFileSync(0, "utf8"));
} catch {
  process.exit(0);
}
const file = String(input.tool_input?.file_path ?? "").replaceAll("\\", "/");
const resolved = resolve(input.cwd ?? process.cwd(), file);

if (/\/plugins\/[^/]+\/\.claude-plugin\/types\//i.test(resolved)) {
  console.error(
    "plugins/*/.claude-plugin/types/ is generated by Claude Code and git-ignored. Run `mise run plugins:types` instead of editing it."
  );
  process.exit(2);
}
